	/*  Serach in ledger till date report */
	function ledger_till_date_report(){		
		$data['tdledger'] = $this->Tbl_openno_model->ledger_till_date_result($_POST);
		//echo '<pre>'; print_r($data['tdledger']['today']); echo '</pre>'; die;
		foreach($data['tdledger']['before'] as $key => $val){
			 $finalsum=0;
		$data['shift_name'] = $val['ShiftId'];
		$data['search_party'] = $val['PartyId'];
		$data['todate'] = $val['Date'];
		$tdata = $this->Tbl_transactions_model->view_transaction_filter($data);
		//echo '<pre>'; print_r($tdata); echo '</pre>'; //die;
		foreach($tdata as $keyy => $vall){
			
			$finalsum += array_sum(explode(',',$vall['trn_amt']));
			//echo $finalsum.' tt ';
		}
		$data['tdledger']['before'][$key]['finalsum'] = $finalsum;
		$data['tdledger']['before'][$key]['tamnt'] = $finalsum;
		//echo '<pre>'; print_r($data['tdledger']['before']); echo '</pre>';
		//$tamnt = explode(',',$val['trn_amt']);
		}
		foreach($data['tdledger']['today'] as $key => $val){
			 $finalsum=0;
		$data['shift_name'] = $val['ShiftId'];
		$data['search_party'] = $val['PartyId'];
		$data['todate'] = $val['Date'];
		$tdata = $this->Tbl_transactions_model->view_transaction_filter($data);
		//echo '<pre>'; print_r($tdata); echo '</pre>'; //die;
		foreach($tdata as $keyy => $vall){
			
			$finalsum += array_sum(explode(',',$vall['trn_amt']));
			//echo $finalsum.' tt ';
		}
		$data['tdledger']['today'][$key]['finalsum'] = $finalsum;
		$data['tdledger']['today'][$key]['tamnt'] = $finalsum;
		//echo '<pre>'; print_r($tdata); echo '</pre>';
		//$tamnt = explode(',',$val['trn_amt']);
		}
		//echo '<pre>'; print_r($data['tdledger']); echo '</pre>';
		//die;
		$data['kist'] = $this->Tbl_openno_model->ledger_get_kist($_POST);
		$netprofit = $this->Tbl_openno_model->ledger_get_netprofit($_POST);
		$voucher = $this->Tbl_openno_model->ledger_get_voucher($_POST);
		$backvoucher = $this->Tbl_openno_model->ledger_get_back_voucher($_POST);
		$tpamnt = $this->Tbl_openno_model->ledger_get_tpamnt($_POST);
		//echo '<pre>'; print_r($data['kist']); die;
		$np=0;
		foreach($netprofit as $key => $val){
			$np=$np+$val['Net_profit'];
		}
		$tpamntt=0;
		foreach($tpamnt as $key => $val){
			$tpamntt=$tpamntt+(($val['Net_profit']*$val['TP_perc'])/100);
		}
		$vc=0;
	//	echo '<pre>'; print_r($voucher); echo '</pre>'; die;
		 foreach($voucher as $key => $val){
			if($_POST['ledger_id'] == $val['PartyId']){
			$vc=$vc-$val['Amount'];
			}
			if($_POST['ledger_id'] == $val['Collect_By']){
			$vc=$vc+$val['Amount'];
			} 
		}
		$bvc=0;
	//	echo '<pre>'; print_r($voucher); echo '</pre>'; die;
		 foreach($backvoucher as $key => $val){
			if($_POST['ledger_id'] == $val['PartyId']){
			$bvc=$bvc-$val['Amount'];
			}
			if($_POST['ledger_id'] == $val['Collect_By']){
			$bvc=$bvc+$val['Amount'];
			} 
		}
		//echo '<pre>'; print_r($bvc); echo '</pre>'; die;
		//echo $np.' net profit '; echo $vc.' voucher '; echo $tpamntt.' tp amount '; die;
		//$data['ob'] = $np - $vc + $tpamntt;
		$data['ob'] = $vc;
		$data['backvoucher'] = $bvc;
		//echo '<pre>'; print_r($data); echo '</pre>'; die;
		$data['_view'] = 'tbl_openno/view_till_date_ledger';
                $this->load->view('layouts/main',$data);
	}
	

    /*
     * Deleting tbl_openno
     */
    function remove($id)
    {
        $tbl_openno = $this->Tbl_openno_model->get_tbl_openno($id);

        // check if the tbl_openno exists before trying to delete it
        if(isset($tbl_openno['id']))
        {
           return $this->Tbl_openno_model->delete_tbl_openno($id);
            //redirect('tbl_openno/index');
        }
        else
            show_error('The tbl_openno you are trying to delete does not exist.');
    }
    
